mapper.delete:
DELETE FROM follow
WHERE follower_email = #{followerEmail}
  AND followee_email = #{followeeEmail}

mapper.select:
SELECT

FROM follow f
JOIN "user" u ON u.email = f.follower_email

WHERE f.followee_email = #{email}
ORDER BY f.created_at DESC, u.email
LIMIT #{limit} OFFSET #{offset}

